import React from 'react';
import { useOutletContext } from 'react-router-dom';

const Sec_P2 = () => {
  const context = useOutletContext();
  const { data: securityData, setter: setSecurityData } = context?.sec || {};
  const resumeData = Array.isArray(context) ? context[0] : context?.resumeData;

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="sec" links={["Ingestion", "Threat", "IAM", "Audits"]} />
      <div className="summary-box">
        <h3>Threat Boundary Matrix Assessment</h3>
        <p stye={{ marginTop: '1rem' }}>{resumeData ? `Analyzed signature profile threat scanning anomaly risk profile score: ${(100 - resumeData.score)}% risk margin.` : "Scanning vector pipeline empty."}</p>
      </div>
    </div>
  );
};
export default Sec_P2;
